import SwiftUI

// MARK: - 앱 언어
enum AppLanguage: String, CaseIterable, Identifiable {
    case korean = "ko"
    case english = "en"
    case japanese = "ja"
    case chinese = "zh"
    case german = "de"
    case french = "fr"
    case spanish = "es"
    case italian = "it"
    case portuguese = "pt"
    case chineseTraditional = "zh-Hant"
    case dutch = "nl"
    case swedish = "sv"
    case norwegian = "nb"
    case danish = "da"
    case finnish = "fi"
    case polish = "pl"
    case czech = "cs"
    case greek = "el"
    case turkish = "tr"
    case russian = "ru"
    case indonesian = "id"

    var id: String { rawValue }

    var displayName: String {
        switch self {
        case .korean: return "한국어"
        case .english: return "English"
        case .swedish: return "Svenska"
        case .norwegian: return "Norsk"
        case .danish: return "Dansk"
        case .finnish: return "Suomi"
        case .polish: return "Polski"
        case .czech: return "Čeština"
        case .greek: return "Ελληνικά"
        case .turkish: return "Türkçe"
        case .russian: return "Русский"
        case .indonesian: return "Bahasa Indonesia"
        case .dutch: return "Nederlands"
        case .japanese: return "日本語"
        case .chinese: return "中文"
        case .german: return "Deutsch"
        case .french: return "Français"
        case .spanish: return "Español"
        case .italian: return "Italiano"
        case .portuguese: return "Português (Brasil)"
        case .chineseTraditional: return "繁體中文"
        }
    }

    var flag: String {
        switch self {
        case .korean: return "🇰🇷"
        case .english: return "🇺🇸"
        case .swedish: return "🇸🇪"
        case .norwegian: return "🇳🇴"
        case .danish: return "🇩🇰"
        case .finnish: return "🇫🇮"
        case .polish: return "🇵🇱"
        case .czech: return "🇨🇿"
        case .greek: return "🇬🇷"
        case .turkish: return "🇹🇷"
        case .russian: return "🇷🇺"
        case .indonesian: return "🇮🇩"
        case .dutch: return "🇳🇱"
        case .japanese: return "🇯🇵"
        case .chinese: return "🇨🇳"
        case .german: return "🇩🇪"
        case .french: return "🇫🇷"
        case .spanish: return "🇪🇸"
        case .italian: return "🇮🇹"
        case .portuguese: return "🇧🇷"
        case .chineseTraditional: return "🇹🇼"
        }
    }

    /// 번들 리소스(문자열 카탈로그·LeeoKit)를 고를 때 쓰는 코드.
    /// ⚠️ 중국어는 `zh`가 아니라 `zh-Hans`여야 카탈로그가 매칭된다.
    var bundleLanguageCode: String {
        switch self {
        case .korean: return "ko"
        case .english: return "en"
        case .swedish: return "sv"
        case .norwegian: return "nb"
        case .danish: return "da"
        case .finnish: return "fi"
        case .polish: return "pl"
        case .czech: return "cs"
        case .greek: return "el"
        case .turkish: return "tr"
        case .russian: return "ru"
        case .indonesian: return "id"
        case .dutch: return "nl"
        case .japanese: return "ja"
        case .chinese: return "zh-Hans"
        case .german: return "de"
        case .french: return "fr"
        case .spanish: return "es"
        case .italian: return "it"
        case .portuguese: return "pt-BR"
        case .chineseTraditional: return "zh-Hant"
        }
    }

    static var current: AppLanguage {
        get {
            if let raw = UserDefaults.standard.string(forKey: "appLanguage"),
               let lang = AppLanguage(rawValue: raw) {
                return lang
            }
            return AppLanguage.fromDeviceLocale()
        }
        set {
            UserDefaults.standard.set(newValue.rawValue, forKey: "appLanguage")
            // 앱 번들 문구(LeeoKit 피드백 화면, 시스템 공유 시트 등)는 이 앱의 언어 설정이 아니라
            // **번들 언어**를 따른다. 이 값을 같이 써 둬야 기기 언어가 한국어인 사용자가 앱만
            // 영어로 바꿨을 때 그 화면들까지 따라온다.
            // ⚠️ 번들 문구는 **다음 실행부터** 반영된다(이미 로드된 번들 캐시는 안 바뀐다).
            //    설정 화면의 행 이름들은 Strings 를 쓰므로 즉시 바뀐다.
            // 지원하지 않는 언어에서 개발 언어(한국어)로 떨어지지 않도록 영어를 뒤에 둔다.
            let fallback = newValue == .english ? [] : ["en"]
            UserDefaults.standard.set([newValue.bundleLanguageCode] + fallback, forKey: "AppleLanguages")
            LanguageManager.shared.currentLanguage = newValue
        }
    }

    /// 디바이스 선호 언어 → 지원 언어. 미지원이면 영어.
    /// `Locale.preferredLanguages`는 사용자 우선순위 순서로 정렬되어 있어
    /// 첫 번째 일치 항목을 사용한다.
    static func fromDeviceLocale() -> AppLanguage {
        for code in Locale.preferredLanguages {
            let prefix = code.split(separator: "-").first.map(String.init) ?? code
            switch prefix {
            case "ko": return .korean
            case "ja": return .japanese
            case "zh":
                // zh-Hant-TW, zh-Hant-HK, zh-HK, zh-TW → 번체
                let rest = code.split(separator: "-").dropFirst().map(String.init)
                return rest.contains(where: { ["Hant", "TW", "HK", "MO"].contains($0) }) ? .chineseTraditional : .chinese
            case "de": return .german
            case "fr": return .french
            case "es": return .spanish
            case "it": return .italian
            case "pt": return .portuguese
            case "nl": return .dutch
            case "sv": return .swedish
            case "da": return .danish
            case "fi": return .finnish
            case "pl": return .polish
            case "cs": return .czech
            case "el": return .greek
            case "tr": return .turkish
            case "ru": return .russian
            case "id", "in": return .indonesian
            case "nb", "no", "nn": return .norwegian
            case "en": return .english
            default: continue
            }
        }
        return .english
    }
}

// MARK: - 러시아어 복수형

/// 러시아어 수사 뒤 명사 꼴 — 1 день · 2 дня · 5 дней (11~14는 дней)
func ruPlural(_ n: Int, _ one: String, _ few: String, _ many: String) -> String {
    let n10 = abs(n) % 10, n100 = abs(n) % 100
    if n10 == 1 && n100 != 11 { return one }
    if (2...4).contains(n10) && !(12...14).contains(n100) { return few }
    return many
}

/// 소수(0.5일 등)는 생격 단수 — 1,5 дня
func ruPlural(_ n: Double, _ one: String, _ few: String, _ many: String) -> String {
    n.rounded() == n ? ruPlural(Int(n), one, few, many) : few
}

// MARK: - 언어 변경 감지용 Observable
@Observable
class LanguageManager {
    static let shared = LanguageManager()
    var currentLanguage: AppLanguage

    private init() {
        if let raw = UserDefaults.standard.string(forKey: "appLanguage"),
           let lang = AppLanguage(rawValue: raw) {
            self.currentLanguage = lang
        } else {
            self.currentLanguage = AppLanguage.fromDeviceLocale()
        }
    }
}

