    static func optimalPlannerSummary(totalDays: Int, breaks: Int, leaveUsed: Int) -> String {
        switch lang {
        case .korean: return "연차 \(leaveUsed)일로 총 \(totalDays)일 휴식 (\(breaks)개의 연휴)"
        case .english: return "\(totalDays) days off with \(leaveUsed) PTO (\(breaks) breaks)"
        case .swedish: return "\(totalDays) lediga dagar med \(leaveUsed) semesterdagar (\(breaks) pauser)"
        case .norwegian: return "\(totalDays) dager fri med \(leaveUsed) feriedager (\(breaks) pauser)"
        case .danish: return "\(totalDays) dage fri med \(leaveUsed) feriedage (\(breaks) pauser)"
        case .finnish: return "\(totalDays) vapaapäivää \(leaveUsed) lomapäivällä (\(breaks) taukoa)"
        case .polish: return "Wolne: \(totalDays) dni za \(leaveUsed) dni urlopu (przerwy: \(breaks))"
        case .czech: return "Dní volna: \(totalDays), dovolená: \(leaveUsed) d (pauz: \(breaks))"
        case .greek: return "\(totalDays) ημέρες ρεπό με \(leaveUsed) ημέρες άδειας (\(breaks) διαλείμματα)"
        case .turkish: return "\(leaveUsed) izinle \(totalDays) gün tatil (\(breaks) mola)"
        case .russian: return "\(totalDays) \(ruPlural(totalDays, "день", "дня", "дней")) отдыха за \(leaveUsed) \(ruPlural(leaveUsed, "день", "дня", "дней")) отпуска (\(breaks) \(ruPlural(breaks, "период", "периода", "периодов")))"
        case .indonesian: return "Libur \(totalDays) hari dengan \(leaveUsed) hari cuti (\(breaks) kali libur panjang)"
        case .dutch: return "\(totalDays) dagen vrij met \(leaveUsed) verlofdagen (\(breaks) vakanties)"
        case .japanese: return "有給\(leaveUsed)日で計\(totalDays)日休み（\(breaks)回の連休）"
        case .chinese: return "用\(leaveUsed)天年假休息\(totalDays)天（\(breaks)次假期）"
        case .german: return "\(totalDays) freie Tage mit \(leaveUsed) Urlaubstagen (\(breaks) Auszeiten)"
        case .french: return "\(totalDays) jours de repos avec \(leaveUsed) congés (\(breaks) pauses)"
        case .spanish: return "\(totalDays) días libres con \(leaveUsed == 1 ? "1 día" : "\(leaveUsed) días") de vacaciones (\(breaks == 1 ? "1 puente" : "\(breaks) puentes"))"
        case .italian: return "\(totalDays) giorni liberi con \(leaveUsed == 1 ? "1 giorno" : "\(leaveUsed) giorni") di ferie (\(breaks == 1 ? "1 ponte" : "\(breaks) ponti"))"
        case .portuguese: return "\(totalDays) dias de folga com \(leaveUsed == 1 ? "1 dia" : "\(leaveUsed) dias") de férias (\(breaks == 1 ? "1 feriadão" : "\(breaks) feriadões"))"
        case .chineseTraditional: return "用\(leaveUsed)天特休休息\(totalDays)天（\(breaks)次連假）"
        }
    }

