    /// 일수 표기 — 영어의 "1 days"를 막는다.
    /// (`dayUnitSuffix`는 숫자에 그냥 붙이는 접미사라 단수를 구분하지 못한다)
    static func dayCount(_ value: Double) -> String {
        let text = formatLeave(value)
        switch lang {
        case .korean: return "\(text)일"
        case .english: return value == 1 ? "1 day" : "\(text) days"
        case .swedish: return value == 1 ? "1 dag" : "\(text) dagar"
        case .norwegian: return value == 1 ? "1 dag" : "\(text) dager"
        case .danish: return value == 1 ? "1 dag" : "\(text) dage"
        case .finnish: return value == 1 ? "1 päivä" : "\(text) päivää"
        case .polish: return value == 1 ? "1 dzień" : "\(text) dni"
        case .czech: return value == 1 ? "1 den" : "\(text) d"
        case .greek: return value == 1 ? "1 ημέρα" : "\(text) ημέρες"
        case .turkish: return value == 1 ? "1 gün" : "\(text) gün"
        case .russian: return value == 1 ? "\(text) \(ruPlural(value, "день", "дня", "дней"))" : "\(text) \(ruPlural(value, "день", "дня", "дней"))"
        case .indonesian: return value == 1 ? "1 hari" : "\(text) hari"
        case .dutch: return value == 1 ? "1 dag" : "\(text) dagen"
        case .japanese: return "\(text)日"
        case .chinese: return "\(text)天"
        case .german: return value == 1 ? "1 Tag" : "\(text) Tage"
        case .french: return value == 1 ? "1 jour" : "\(text) jours"
        case .spanish: return value == 1 ? "1 día" : "\(text) días"
        case .italian: return value == 1 ? "1 giorno" : "\(text) giorni"
        case .portuguese: return value == 1 ? "1 dia" : "\(text) dias"
        case .chineseTraditional: return "\(text)天"
        }
    }

