    static func seasonTag(for month: Int) -> String {
        switch month {
        case 3, 4, 5: return seasonName(.spring)
        case 6, 7, 8: return seasonName(.summer)
        case 9, 10, 11: return seasonName(.fall)
        default: return seasonName(.winter)
        }
