    static func noLeaveDaysOff(weekdayStart: String, weekdayEnd: String, holidayDesc: String, totalDays: Int) -> String {
        switch lang {
        case .korean:
            return "\(weekdayStart)~\(weekdayEnd) \(holidayDesc)로 연차 없이 \(totalDays)일 연휴!"
        case .english:
            return "\(weekdayStart)-\(weekdayEnd): \(totalDays) days off with \(holidayDesc), no leave needed!"
        case .swedish:
            return "\(weekdayStart)–\(weekdayEnd): \(totalDays) lediga dagar med \(holidayDesc), ingen semester behövs!"
        case .norwegian:
            return "\(weekdayStart)–\(weekdayEnd): \(totalDays) dager fri med \(holidayDesc), uten behov for ferie!"
        case .danish:
            return "\(weekdayStart)-\(weekdayEnd): \(totalDays) dage fri med \(holidayDesc), uden brug af ferie!"
        case .finnish:
            return "\(weekdayStart)-\(weekdayEnd): \(totalDays) vapaapäivää (\(holidayDesc)), lomaa ei tarvita!"
        case .polish:
            return "\(weekdayStart)-\(weekdayEnd): \(totalDays) dni wolnego dzięki \(holidayDesc), bez urlopu!"
        case .czech:
            return "\(weekdayStart)-\(weekdayEnd): volno \(totalDays) d díky \(holidayDesc), dovolená není potřeba!"
        case .greek:
            return "\(weekdayStart)-\(weekdayEnd): \(totalDays) ημέρες ρεπό με \(holidayDesc), χωρίς άδεια!"
        case .turkish:
            return "\(weekdayStart)-\(weekdayEnd): \(holidayDesc) ile \(totalDays) gün tatil, izin gerekmiyor!"
        case .russian:
            return "\(weekdayStart)–\(weekdayEnd): \(holidayDesc) — \(totalDays) \(ruPlural(totalDays, "день", "дня", "дней")) отдыха без отпуска!"
        case .indonesian:
            return "\(weekdayStart)-\(weekdayEnd): libur \(totalDays) hari berkat \(holidayDesc), tanpa cuti!"
        case .dutch:
            return "\(weekdayStart)-\(weekdayEnd): \(totalDays) dagen vrij met \(holidayDesc), zonder verlof!"
        case .japanese:
            return "\(weekdayStart)〜\(weekdayEnd) \(holidayDesc)で有給なし\(totalDays)日連休！"
        case .chinese:
            return "\(weekdayStart)~\(weekdayEnd) \(holidayDesc)，无需年假\(totalDays)天假期！"
        case .german: return "\(weekdayStart)–\(weekdayEnd): \(totalDays) freie Tage mit \(holidayDesc), ohne Urlaub!"
        case .french: return "\(weekdayStart)–\(weekdayEnd) : \(totalDays) jours off avec \(holidayDesc), sans congé !"
        case .spanish: return "\(weekdayStart)–\(weekdayEnd): \(totalDays) días libres con \(holidayDesc), ¡sin gastar vacaciones!"
        case .italian: return "\(weekdayStart)–\(weekdayEnd): \(totalDays) giorni liberi con \(holidayDesc), senza ferie!"
        case .portuguese: return "\(weekdayStart)–\(weekdayEnd): \(totalDays) dias de folga com \(holidayDesc), sem usar férias!"
