    static func dateFormat(style: String) -> String {
        switch style {
        case "monthDay":
            switch lang {
            case .korean: return "M월 d일 (E)"
            case .english: return "MMM d (E)"
            case .swedish: return "d MMM (E)"
            case .norwegian: return "d. MMM (E)"
            case .danish: return "d. MMM (E)"
            case .finnish: return "E d.M."
            case .polish: return "d MMM (E)"
            case .czech: return "d. MMM (E)"
            case .greek: return "d MMM (E)"
            case .turkish: return "d MMM (E)"
            case .russian: return "d MMM (E)"
            case .indonesian: return "d MMM (E)"
            case .dutch: return "d MMM (E)"
            case .japanese: return "M月d日(E)"
            case .chinese: return "M月d日(E)"
            case .german: return "d. MMM (E)"
            case .french: return "E d MMM"
            case .spanish: return "E d MMM"
            case .italian: return "E d MMM"
            case .portuguese: return "E, d 'de' MMM"
            case .chineseTraditional: return "M月d日 (E)"
            }
        case "monthDayOnly":
            switch lang {
            case .korean: return "M월 d일"
            case .english: return "MMM d"
            case .swedish: return "d MMM"
            case .norwegian: return "d. MMM"
            case .danish: return "d. MMM"
            case .finnish: return "d.M."
            case .polish: return "d MMM"
            case .czech: return "d. MMM"
            case .greek: return "d MMM"
            case .turkish: return "d MMM"
            case .russian: return "d MMM"
            case .indonesian: return "d MMM"
            case .dutch: return "d MMM"
            case .japanese: return "M月d日"
            case .chinese: return "M月d日"
            case .german: return "d. MMM"
            case .french: return "d MMM"
