    // Accessibility
    static func accessibilityDayLabel(day: Int, isToday: Bool, isHoliday: Bool, isLeave: Bool, isSelected: Bool) -> String {
        var parts: [String] = ["\(day)\(dayUnitSuffix)"]
        if isToday { parts.append(today) }
        if isHoliday { parts.append(holiday) }
        if isLeave { parts.append(annualLeave) }
        if isSelected {
            switch lang {
            case .korean: parts.append("선택됨")
            case .english: parts.append("selected")
            case .swedish: parts.append("valda")
            case .norwegian: parts.append("valgt")
            case .danish: parts.append("valgt")
            case .finnish: parts.append("valittu")
            case .polish: parts.append("wybrano")
            case .czech: parts.append("vybráno")
            case .greek: parts.append("επιλεγμένα")
            case .turkish: parts.append("seçili")
            case .russian: parts.append("выбрано")
            case .indonesian: parts.append("dipilih")
            case .dutch: parts.append("geselecteerd")
            case .japanese: parts.append("選択中")
            case .chinese: parts.append("已选中")
            case .german: parts.append("ausgewählt")
            case .french: parts.append("sélectionné")
            case .spanish: parts.append("seleccionado")
            case .italian: parts.append("selezionato")
            case .portuguese: parts.append("selecionado")
            case .chineseTraditional: parts.append("已選取")
            }
        }
        return parts.joined(separator: ", ")
    }

