    // MARK: - 통화 / 가격 표기
    /// 정수 금액을 현재 언어 로케일에 맞게 통화 표기로 변환.
    /// 마이리얼트립 API가 KRW를 반환하므로, 한국어가 아닌 경우에도 KRW로 표기.
    static func currency(_ amount: Int64) -> String {
        let nf = NumberFormatter()
        nf.numberStyle = .decimal
        nf.locale = Locale(identifier: localeIdentifier)
        let n = nf.string(from: NSNumber(value: amount)) ?? "\(amount)"
        switch lang {
        case .korean: return "\(n)원"
        case .english: return "₩\(n)"
        case .swedish: return "₩\(n)"
        case .norwegian: return "₩\(n)"
        case .danish: return "₩\(n)"
        case .finnish: return "₩\(n)"
        case .polish: return "₩\(n)"
        case .czech: return "₩\(n)"
        case .greek: return "₩\(n)"
        case .turkish: return "₩\(n)"
        case .russian: return "\(n) ₩"
        case .indonesian: return "₩\(n)"
        case .dutch: return "₩\(n)"
        case .japanese: return "₩\(n)"
        case .chinese: return "₩\(n)"
        case .german: return "\(n) ₩"
        case .french: return "\(n) ₩"
        case .spanish: return "\(n) ₩"
        case .italian: return "\(n) ₩"
        case .portuguese: return "₩ \(n)"
        case .chineseTraditional: return "₩\(n)"
        }
    }

