    static func burnoutDaysAgo(_ days: Int) -> String {
        switch lang {
        case .korean: return "\(days)일 전"
        case .english: return days == 1 ? "1 day ago" : "\(days) days ago"
        case .swedish: return days == 1 ? "för 1 dag sedan" : "för \(days) dagar sedan"
        case .norwegian: return days == 1 ? "for 1 dag siden" : "for \(days) dager siden"
        case .danish: return days == 1 ? "for 1 dag siden" : "for \(days) dage siden"
