    static func breakDays(_ n: Int) -> String {
        switch lang {
        case .korean: return "\(n)일"
        case .english: return n == 1 ? "1 day" : "\(n) days"
        case .swedish: return n == 1 ? "1 dag" : "\(n) dagar"
        case .norwegian: return n == 1 ? "1 dag" : "\(n) dager"
        case .danish: return n == 1 ? "1 dag" : "\(n) dage"
        case .finnish: return n == 1 ? "1 päivä" : "\(n) päivää"
        case .polish: return n == 1 ? "1 dzień" : "Dni: \(n)"
        case .czech: return n == 1 ? "1 den" : "\(n) d"
        case .greek: return n == 1 ? "1 ημέρα" : "\(n) ημέρες"
        case .turkish: return n == 1 ? "1 day" : "\(n) gün"
        case .russian: return "\(n) \(ruPlural(n, "день", "дня", "дней"))"
        case .indonesian: return "\(n) hari"
        case .dutch: return n == 1 ? "1 dag" : "\(n) dagen"
        case .japanese: return "\(n)日間"
        case .chinese: return "\(n)天"
        case .german: return n == 1 ? "1 Tag" : "\(n) Tage"
        case .french: return n == 1 ? "1 jour" : "\(n) jours"
        case .spanish: return n == 1 ? "1 día" : "\(n) días"
        case .italian: return n == 1 ? "1 giorno" : "\(n) giorni"
        case .portuguese: return n == 1 ? "1 dia" : "\(n) dias"
        case .chineseTraditional: return n == 1 ? "1 天" : "\(n) 天"
        }
    }

