    /// 설정 — 공휴일 앞뒤 제한 근무일 수
    static func blackoutDays(_ n: Int) -> String {
        switch lang {
        case .korean: return n == 1 ? "앞뒤 \(n) 근무일" : "앞뒤 \(n) 근무일"
        case .english: return n == 1 ? "1 working day before and after" : "\(n) working days before and after"
