    static func shareParticipants(_ count: Int) -> String {
        switch lang {
        case .korean: return "참여자 \(count)명"
        case .english: return count == 1 ? "1 participant" : "\(count) participants"
        case .swedish: return count == 1 ? "1 deltagare" : "\(count) deltagare"
        case .norwegian: return count == 1 ? "1 deltaker" : "\(count) deltakere"
        case .danish: return count == 1 ? "1 deltager" : "\(count) deltagere"
        case .finnish: return count == 1 ? "1 osallistuja" : "\(count) osallistujaa"
        case .polish: return count == 1 ? "1 uczestnik" : "Uczestnicy: \(count)"
        case .czech: return count == 1 ? "1 účastník" : "Účastníků: \(count)"
        case .greek: return count == 1 ? "1 συμμετέχων" : "\(count) συμμετέχοντες"
        case .turkish: return count == 1 ? "1 katılımcı" : "\(count) katılımcı"
        case .russian: return "\(count) \(ruPlural(count, "участник", "участника", "участников"))"
        case .indonesian: return "\(count) peserta"
        case .dutch: return count == 1 ? "1 deelnemer" : "\(count) deelnemers"
        case .japanese: return "参加者\(count)人"
        case .chinese: return "\(count)位参与者"
        case .german: return count == 1 ? "1 Teilnehmer" : "\(count) Teilnehmer"
        case .french: return count == 1 ? "1 participant" : "\(count) participants"
        case .spanish: return count == 1 ? "1 participante" : "\(count) participantes"
        case .italian: return count == 1 ? "1 partecipante" : "\(count) partecipanti"
        case .portuguese: return count == 1 ? "1 participante" : "\(count) participantes"
        case .chineseTraditional: return count == 1 ? "1 位參與者" : "\(count) 位參與者"
        }
    }

