    static func shareUpcomingCount(_ count: Int) -> String {
        switch lang {
        case .korean: return "다가오는 휴가 \(count)건"
        case .english: return count == 1 ? "1 upcoming leave" : "\(count) upcoming leaves"
        case .swedish: return count == 1 ? "1 kommande ledighet" : "\(count) kommande ledigheter"
        case .norwegian: return count == 1 ? "1 kommende ferie" : "\(count) kommende ferier"
        case .danish: return count == 1 ? "1 kommende ferie" : "\(count) kommende ferier"
        case .finnish: return count == 1 ? "1 tuleva loma" : "\(count) tulevaa lomaa"
        case .polish: return count == 1 ? "1 nadchodzący urlop" : "Nadchodzące urlopy: \(count)"
        case .czech: return count == 1 ? "1 nadcházející dovolená" : "Nadcházející dovolená: \(count)"
        case .greek: return count == 1 ? "1 επερχόμενη άδεια" : "\(count) επερχόμενες άδειες"
        case .turkish: return count == 1 ? "1 yaklaşan izin" : "\(count) yaklaşan izin"
        case .russian: return "\(count) \(ruPlural(count, "предстоящий отпуск", "предстоящих отпуска", "предстоящих отпусков"))"
        case .indonesian: return "\(count) cuti mendatang"
        case .dutch: return count == 1 ? "1 komend verlof" : "\(count) komende verloven"
        case .japanese: return "今後の休暇\(count)件"
        case .chinese: return "\(count)个即将到来的休假"
        case .german: return count == 1 ? "1 anstehender Urlaub" : "\(count) anstehende Urlaube"
        case .french: return count == 1 ? "1 congé à venir" : "\(count) congés à venir"
        case .spanish: return count == 1 ? "1 descanso próximo" : "\(count) descansos próximos"
        case .italian: return count == 1 ? "1 periodo di ferie in arrivo" : "\(count) periodi di ferie in arrivo"
        case .portuguese: return count == 1 ? "1 folga programada" : "\(count) folgas programadas"
        case .chineseTraditional: return count == 1 ? "即將到來的休假 1 筆" : "即將到來的休假 \(count) 筆"
        }
    }

