    static func familyDday(_ days: Int) -> String {
        switch lang {
        case .korean: return "D-\(days)"
        case .english: return days == 1 ? "in 1 day" : "in \(days) days"
        case .swedish: return days == 1 ? "om 1 dag" : "om \(days) dagar"
        case .norwegian: return days == 1 ? "om 1 dag" : "om \(days) dager"
        case .danish: return days == 1 ? "om 1 dag" : "om \(days) dage"
        case .finnish: return days == 1 ? "1 päivän päästä" : "\(days) päivän päästä"
        case .polish: return days == 1 ? "za 1 dzień" : "za \(days) dni"
        case .czech: return days == 1 ? "za 1 den" : "za \(days) d"
        case .greek: return days == 1 ? "σε 1 ημέρα" : "σε \(days) ημέρες"
        case .turkish: return days == 1 ? "1 gün sonra" : "\(days) gün sonra"
        case .russian: return "через \(days) \(ruPlural(days, "день", "дня", "дней"))"
        case .indonesian: return "\(days) hari lagi"
        case .dutch: return days == 1 ? "over 1 dag" : "over \(days) dagen"
        case .japanese: return "あと\(days)日"
        case .chinese: return "还有\(days)天"
        case .german: return days == 1 ? "in 1 Tag" : "in \(days) Tagen"
        case .french: return days == 1 ? "dans 1 jour" : "dans \(days) jours"
        case .spanish: return days == 1 ? "en 1 día" : "en \(days) días"
        case .italian: return days == 1 ? "tra 1 giorno" : "tra \(days) giorni"
        case .portuguese: return days == 1 ? "em 1 dia" : "em \(days) dias"
        case .chineseTraditional: return days == 1 ? "還有 1 天" : "還有 \(days) 天"
        }
    }
}
